-- Schema de test uniquement, base neuve synthetique du runner ; aucune migration de base existante.
CREATE TABLE mission04_test_marker(nonce text PRIMARY KEY);
CREATE TABLE organisations(id uuid PRIMARY KEY,devise varchar(3) NOT NULL,nom text,slug text,pays text,ville text,adresse text,telephone text,email text,logo_url text,fuseau_horaire text,numero_identification text,site_web text,description text,cree_le timestamptz,modifie_le timestamptz);
CREATE TABLE utilisateurs(id uuid PRIMARY KEY,organisation_id uuid NOT NULL REFERENCES organisations(id),actif boolean NOT NULL DEFAULT true,auth_epoch integer NOT NULL DEFAULT 1,nom text);
CREATE TABLE types_dechets(id uuid PRIMARY KEY,nom text);
CREATE TABLE stocks(id uuid PRIMARY KEY,organisation_id uuid NOT NULL REFERENCES organisations(id),type_dechet_id uuid NOT NULL REFERENCES types_dechets(id),quantite numeric(12,3) NOT NULL CHECK(quantite>=0 AND quantite::text<>'NaN'),unite text NOT NULL DEFAULT 'kg',tracabilite_lots_active boolean NOT NULL,date_mise_a_jour timestamptz DEFAULT now(),UNIQUE(organisation_id,type_dechet_id));
CREATE TABLE lots(id uuid PRIMARY KEY,organisation_id uuid NOT NULL REFERENCES organisations(id),type_dechet_id uuid NOT NULL REFERENCES types_dechets(id),code_qr text NOT NULL UNIQUE,poids_reel numeric(12,3) NOT NULL,quantite_restante_kg numeric(12,3) CHECK(quantite_restante_kg IS NULL OR (quantite_restante_kg>=0 AND quantite_restante_kg<=poids_reel)),statut_lot text NOT NULL,modifie_le timestamptz DEFAULT now(),UNIQUE(organisation_id,id));
CREATE TABLE ventes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organisation_id uuid NOT NULL REFERENCES organisations(id),stock_id uuid NOT NULL REFERENCES stocks(id),quantite numeric(12,3) NOT NULL CHECK(quantite>0),prix_unitaire numeric(12,2) NOT NULL CHECK(prix_unitaire>=0),montant_total numeric(12,2) NOT NULL,devise varchar(3) NOT NULL,acheteur_nom text NOT NULL,reference_vente text,statut text NOT NULL,cree_par uuid NOT NULL REFERENCES utilisateurs(id),provenance_lots_statut text NOT NULL,date_vente timestamptz NOT NULL DEFAULT now(),UNIQUE(organisation_id,id));
CREATE TABLE mouvements_stock(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),stock_id uuid NOT NULL REFERENCES stocks(id),lot_id uuid REFERENCES lots(id),vente_id uuid REFERENCES ventes(id),type_mouvement text NOT NULL CHECK(type_mouvement IN ('ENTREE','SORTIE')),quantite numeric(12,3) NOT NULL CHECK(quantite>0),date_mouvement timestamptz NOT NULL DEFAULT now(),CHECK((type_mouvement='ENTREE' AND lot_id IS NOT NULL AND vente_id IS NULL) OR (type_mouvement='SORTIE' AND lot_id IS NULL AND vente_id IS NOT NULL)));
CREATE UNIQUE INDEX entree_lot_unique ON mouvements_stock(lot_id) WHERE type_mouvement='ENTREE';
CREATE TABLE vente_lots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organisation_id uuid NOT NULL,vente_id uuid NOT NULL,lot_id uuid NOT NULL,quantite_kg numeric(12,3) NOT NULL CHECK(quantite_kg>0),cree_le timestamptz DEFAULT now(),UNIQUE(vente_id,lot_id),FOREIGN KEY(organisation_id,vente_id) REFERENCES ventes(organisation_id,id),FOREIGN KEY(organisation_id,lot_id) REFERENCES lots(organisation_id,id));
CREATE TABLE facteurs_carbone(id uuid PRIMARY KEY, type_dechet_id uuid NOT NULL REFERENCES types_dechets(id),facteur_kg_co2e_par_kg numeric(12,6) NOT NULL,statut text NOT NULL,date_debut_validite timestamptz NOT NULL,date_fin_validite timestamptz,source text,version_source text,zone_geographique text);
CREATE TABLE impacts_carbone(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vente_id uuid NOT NULL REFERENCES ventes(id),facteur_carbone_id uuid NOT NULL REFERENCES facteurs_carbone(id),quantite_kg numeric(12,3) NOT NULL,facteur_utilise numeric(12,6) NOT NULL,co2e_estime_kg numeric(18,6) NOT NULL,date_calcul timestamptz DEFAULT now());
